// ============ Funciones auxiliares de dibujo ============
let _id = 0;
const uid = (p) => `${p}${++_id}`;

const PAL = {
  oro: ["#fbe9b4", "#d4a94c", "#7a5218"],
  plata: ["#fafafa", "#b3b3b8", "#5b5b61"],
  cobre: ["#f6c39b", "#bb6a3f", "#5a2813"],
  bronce: ["#e9cf92", "#a9803a", "#4e3714"],
  bimetal: ["#f3f3f3", "#a8a8ad", "#4f4f55"],
};

function starPath(cx, cy, R, r, n = 5) {
  let d = "";
  for (let i = 0; i < n * 2; i++) {
    const ang = (Math.PI / n) * i - Math.PI / 2;
    const rad = i % 2 ? r : R;
    d +=
      (i ? "L" : "M") +
      (cx + Math.cos(ang) * rad).toFixed(1) +
      " " +
      (cy + Math.sin(ang) * rad).toFixed(1);
  }
  return d + "Z";
}

function motif(kind, c) {
  const stroke = `stroke="${c[2]}" stroke-width="1" stroke-opacity=".7"`;
  switch (kind) {
    case "star":
      return `<path d="${starPath(100, 100, 40, 17)}" fill="${c[0]}" ${stroke}/><circle cx="100" cy="100" r="7" fill="${c[2]}" fill-opacity=".6"/>`;
    case "sun": {
      let rays = "";
      for (let i = 0; i < 16; i++) {
        const a = (i * Math.PI) / 8;
        rays += `<path d="M${100 + Math.cos(a) * 22} ${100 + Math.sin(a) * 22}L${100 + Math.cos(a + 0.1) * 40} ${100 + Math.sin(a + 0.1) * 40}L${100 + Math.cos(a - 0.1) * 40} ${100 + Math.sin(a - 0.1) * 40}Z" fill="${c[0]}" ${stroke}/>`;
      }
      return `${rays}<circle cx="100" cy="100" r="19" fill="${c[1]}" ${stroke}/><circle cx="100" cy="100" r="11" fill="${c[0]}" fill-opacity=".7"/>`;
    }
    case "shield":
      return `<path d="M72 68h56v34c0 20-14 32-28 38-14-6-28-18-28-38z" fill="${c[1]}" ${stroke}/><path d="M100 72v64M76 96h48" stroke="${c[2]}" stroke-width="3" stroke-opacity=".7"/><circle cx="100" cy="96" r="6" fill="${c[0]}"/>`;
    case "cross":
      return `<path d="M92 62h16v28h28v16h-28v34h-16v-34H64V90h28z" fill="${c[1]}" ${stroke}/><circle cx="100" cy="98" r="6" fill="${c[0]}"/>`;
    case "laurel": {
      let l = "";
      for (let i = 0; i < 9; i++) {
        const t = i / 8,
          y = 138 - t * 66,
          x = 62 + Math.sin(t * 1.6) * 8;
        l += `<ellipse cx="${x}" cy="${y}" rx="9" ry="4" transform="rotate(${-50 + t * 30} ${x} ${y})" fill="${c[1]}" ${stroke}/><ellipse cx="${200 - x}" cy="${y}" rx="9" ry="4" transform="rotate(${50 - t * 30} ${200 - x} ${y})" fill="${c[1]}" ${stroke}/>`;
      }
      return l;
    }
    case "pillars":
      return `<rect x="70" y="70" width="12" height="62" fill="${c[1]}" ${stroke}/><rect x="118" y="70" width="12" height="62" fill="${c[1]}" ${stroke}/><path d="M64 70h72M64 136h72" stroke="${c[2]}" stroke-width="4"/><path d="M82 100q18-26 36 0q-18 26-36 0z" fill="${c[0]}" ${stroke}/>`;
    default:
      return "";
  }
}

function coin(o) {
  const c = PAL[o.metal] || PAL.oro,
    g = uid("g"),
    h = uid("h"),
    t = uid("t"),
    r = uid("r");
  const center = o.metal === "bimetal" ? PAL.oro : c;
  const ringText = (o.ring || "REPÚBLICA · MONEDA").toUpperCase();
  const denom = o.denom
    ? `<text x="100" y="${o.denomY || 128}" text-anchor="middle" font-family="Cormorant Garamond,serif" font-weight="700" font-size="${o.denomSize || 30}" fill="${c[2]}" fill-opacity=".85" stroke="${c[0]}" stroke-width=".4">${o.denom}</text>`
    : "";
  return `<svg viewBox="0 0 200 200" class="piece" role="img" aria-label="${o.alt || "Moneda"}" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <radialGradient id="${g}" cx="35%" cy="28%" r="85%"><stop offset="0" stop-color="${c[0]}"/><stop offset=".5" stop-color="${c[1]}"/><stop offset="1" stop-color="${c[2]}"/></radialGradient>
    <radialGradient id="${r}" cx="40%" cy="30%" r="90%"><stop offset="0" stop-color="${center[0]}"/><stop offset=".55" stop-color="${center[1]}"/><stop offset="1" stop-color="${center[2]}"/></radialGradient>
    <linearGradient id="${h}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".65"/><stop offset=".4" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".35"/></linearGradient>
    <path id="${t}" d="M100,100 m-80,0 a80,80 0 1,1 160,0 a80,80 0 1,1 -160,0"/>
  </defs>
  <circle cx="100" cy="100" r="96" fill="url(#${g})"/>
  <circle cx="100" cy="100" r="92" fill="none" stroke="${c[2]}" stroke-opacity=".55" stroke-width="1.2" stroke-dasharray="1.6 3.2"/>
  <circle cx="100" cy="100" r="88" fill="none" stroke="${c[0]}" stroke-opacity=".6" stroke-width=".8"/>
  <circle cx="100" cy="100" r="62" fill="url(#${r})" stroke="${c[2]}" stroke-opacity=".7" stroke-width="1.4"/>
  <circle cx="100" cy="100" r="58" fill="none" stroke="${c[0]}" stroke-opacity=".5" stroke-width=".6"/>
  <text font-family="Cinzel,serif" font-size="11.5" letter-spacing="3.2" fill="${c[2]}" fill-opacity=".9"><textPath href="#${t}" startOffset="0">${ringText} ★ ${o.year || ""} ★</textPath></text>
  ${motif(o.motif, o.metal === "bimetal" ? PAL.oro : c)}
  ${denom}
  <circle cx="100" cy="100" r="96" fill="url(#${h})"/>
</svg>`;
}

function bill(o) {
  const [a, b, d] = o.colors || ["#8b2f45", "#b84a62", "#3a0f1a"];
  const bg = uid("b"),
    cl = uid("c"),
    hl = uid("hl");
  let guil = "";
  for (let k = 0; k < 14; k++) {
    let p = `M0 ${70 + k * 5}`;
    for (let x = 0; x <= 400; x += 10) {
      p += ` L${x} ${(70 + k * 5 + Math.sin(x / 22 + k * 0.55) * (9 + k * 0.6)).toFixed(1)}`;
    }
    guil += `<path d="${p}" fill="none" stroke="#fff" stroke-opacity=".10" stroke-width=".7"/>`;
  }
  let rosette = "";
  for (let i = 0; i < 12; i++)
    rosette += `<ellipse cx="78" cy="100" rx="30" ry="9" transform="rotate(${i * 15} 78 100)" fill="none" stroke="${d}" stroke-opacity=".5" stroke-width=".8"/>`;
  return `<svg viewBox="0 0 400 200" class="piece" role="img" aria-label="${o.alt || "Billete"}" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="${bg}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${a}"/><stop offset=".55" stop-color="${b}"/><stop offset="1" stop-color="${d}"/></linearGradient>
    <clipPath id="${cl}"><rect x="6" y="6" width="388" height="188" rx="6"/></clipPath>
    <linearGradient id="${hl}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".30"/><stop offset=".35" stop-color="#fff" stop-opacity="0"/></linearGradient>
  </defs>
  <rect x="6" y="6" width="388" height="188" rx="6" fill="#e9dcc0"/>
  <g clip-path="url(#${cl})">
    <rect x="6" y="6" width="388" height="188" fill="url(#${bg})" opacity=".92"/>
    ${guil}
    <rect x="6" y="6" width="388" height="188" fill="url(#${hl})"/>
  </g>
  <rect x="14" y="14" width="372" height="172" rx="3" fill="none" stroke="#f3e3b8" stroke-opacity=".85" stroke-width="1.4"/>
  <rect x="20" y="20" width="360" height="160" rx="2" fill="none" stroke="#f3e3b8" stroke-opacity=".4" stroke-width=".7" stroke-dasharray="2 3"/>
  <circle cx="78" cy="100" r="46" fill="#f3e3b8" fill-opacity=".14" stroke="#f3e3b8" stroke-opacity=".8" stroke-width="1.2"/>
  ${rosette}
  <path d="${starPath(78, 100, 20, 8, 8)}" fill="#f3e3b8" fill-opacity=".85" stroke="${d}" stroke-width=".8"/>
  <text x="228" y="52" text-anchor="middle" font-family="Cinzel,serif" font-size="13" letter-spacing="3" fill="#f6e8c3">${(o.issuer || "BANCO").toUpperCase()}</text>
  <line x1="150" y1="60" x2="306" y2="60" stroke="#f3e3b8" stroke-opacity=".6" stroke-width=".8"/>
  <text x="228" y="122" text-anchor="middle" font-family="Cormorant Garamond,serif" font-weight="700" font-size="${o.denomSize || 62}" fill="#fff6dc" stroke="${d}" stroke-width="1" paint-order="stroke">${o.denom}</text>
  <text x="228" y="146" text-anchor="middle" font-family="Cinzel,serif" font-size="10.5" letter-spacing="4" fill="#f6e8c3">${(o.unit || "PESOS").toUpperCase()}</text>
  <text x="46" y="171" font-family="Cinzel,serif" font-size="8.5" letter-spacing="2" fill="#f6e8c3" fill-opacity=".9">${o.serial || "A 00000000"}</text>
  <circle cx="352" cy="152" r="18" fill="none" stroke="#f3e3b8" stroke-width="1.1"/>
  <path d="${starPath(352, 152, 10, 4.5)}" fill="#f3e3b8" fill-opacity=".9"/>
  <text x="352" y="42" text-anchor="middle" font-family="Cormorant Garamond,serif" font-weight="700" font-size="24" fill="#fff6dc">${o.corner || o.denom}</text>
</svg>`;
}

/* ============ Reversos ============ */
function billBack(o) {
  const [a, b, d] = o.colors || ["#8b2f45", "#b84a62", "#3a0f1a"];
  const bg = uid("bb"),
    cl = uid("bc");
  let guil = "";
  for (let k = 0; k < 12; k++) {
    let p = `M0 ${20 + k * 14}`;
    for (let x = 0; x <= 400; x += 10)
      p += ` L${x} ${(20 + k * 14 + Math.cos(x / 18 + k * 0.7) * 7).toFixed(1)}`;
    guil += `<path d="${p}" fill="none" stroke="#fff" stroke-opacity=".09" stroke-width=".7"/>`;
  }
  let scene = "";
  if (o.scene === "columns") {
    for (let i = 0; i < 5; i++)
      scene += `<rect x="${128 + i * 34}" y="78" width="14" height="58" fill="#f3e3b8" fill-opacity=".85"/>`;
    scene += `<path d="M116 78h168l-84-26z" fill="#f3e3b8" fill-opacity=".9"/><rect x="112" y="136" width="176" height="8" fill="#f3e3b8" fill-opacity=".9"/>`;
  } else if (o.scene === "river") {
    scene += `<circle cx="250" cy="70" r="12" fill="#f3e3b8" fill-opacity=".9"/><path d="M110 118L150 88L186 112L228 82L290 122V148H110z" fill="#f3e3b8" fill-opacity=".35"/>`;
    for (let i = 0; i < 4; i++)
      scene += `<path d="M112 ${124 + i * 7} q14 -6 28 0 t28 0 t28 0 t28 0 t28 0 t28 0" fill="none" stroke="#f3e3b8" stroke-width="1.4" stroke-opacity=".85"/>`;
    scene += `<path d="M150 62q6-6 12 0q6-6 12 0M180 76q5-5 10 0q5-5 10 0" fill="none" stroke="#f3e3b8" stroke-width="1.2"/>`;
  } else {
    scene += `<circle cx="252" cy="68" r="12" fill="#f3e3b8" fill-opacity=".9"/><path d="M110 148L150 98L172 122L212 70L250 118L272 100L290 148z" fill="#f3e3b8" fill-opacity=".85"/><path d="M212 70L200 88L212 84L222 92z" fill="${d}" fill-opacity=".35"/>`;
  }
  const small = String(o.denom).length > 3;
  const fs = small ? 22 : 40;
  return `<svg viewBox="0 0 400 200" role="img" aria-label="${o.alt || "Reverso de billete"}" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="${bg}" x1="1" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${a}"/><stop offset=".5" stop-color="${b}"/><stop offset="1" stop-color="${d}"/></linearGradient>
    <clipPath id="${cl}"><rect x="6" y="6" width="388" height="188" rx="6"/></clipPath>
  </defs>
  <rect x="6" y="6" width="388" height="188" rx="6" fill="#e9dcc0"/>
  <g clip-path="url(#${cl})"><rect x="6" y="6" width="388" height="188" fill="url(#${bg})" opacity=".92"/>${guil}</g>
  <rect x="14" y="14" width="372" height="172" rx="3" fill="none" stroke="#f3e3b8" stroke-opacity=".85" stroke-width="1.4"/>
  <rect x="20" y="20" width="360" height="160" rx="2" fill="none" stroke="#f3e3b8" stroke-opacity=".4" stroke-width=".7" stroke-dasharray="2 3"/>
  <text x="200" y="38" text-anchor="middle" font-family="Cinzel,serif" font-size="11" letter-spacing="3.5" fill="#f6e8c3">${(o.title || "Paisaje").toUpperCase()}</text>
  <rect x="110" y="46" width="180" height="104" fill="${d}" fill-opacity=".55" stroke="#f3e3b8" stroke-opacity=".85" stroke-width="1.2"/>
  ${scene}
  <text x="62" y="108" text-anchor="middle" font-family="Cormorant Garamond,serif" font-weight="700" font-size="${fs}" fill="#fff6dc" stroke="${d}" stroke-width=".8" paint-order="stroke">${o.denom}</text>
  <text x="338" y="108" text-anchor="middle" font-family="Cormorant Garamond,serif" font-weight="700" font-size="${fs}" fill="#fff6dc" stroke="${d}" stroke-width=".8" paint-order="stroke">${o.denom}</text>
  <text x="200" y="168" text-anchor="middle" font-family="Cinzel,serif" font-size="8.5" letter-spacing="2.4" fill="#f6e8c3" fill-opacity=".9">${(o.legend || "Pagadero al portador").toUpperCase()}</text>
</svg>`;
}

